# Fix the transform to properly handle uniform rows
def transform_fixed(grid):
    """
    Transform rule for task-000641e2:
    - Uniform rows (all same color): keep unchanged
    - Mixed rows: preserve first contiguous run at start, change all subsequent runs to 1s
    """
    result = []
    for row in grid:
        is_uniform = all(x == row[0] for x in row) if row else True
        if is_uniform:
            result.append(row.copy())
        else:
            new_row = []
            i = 0
            while i < len(row):
                current_color = row[i]
                j = i
                while j < len(row) and row[j] == current_color:
                    j += 1
                run_len = j - i
                if i == 0:
                    for k in range(run_len):
                        new_row.append(current_color)
                else:
                    for k in range(run_len):
                        new_row.append(1)
                i = j
            result.append(new_row)
    return result

